<?php
require dirname(__DIR__).'/app/web.php';requireAuth();requireAnyPermission(['audit.view']);
$legacy=($_GET['source']??'')==='legacy';$table=$legacy?'legacy_audit_logs':'audit_logs';$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*30;
