?><nav class="module-tabs"><a href="/audit.php" <?=$legacy?'':'class="active"'?>>MIS activity</a><a href="/audit.php?source=legacy" <?=$legacy?'class="active"':''?>>Imported website history</a></nav><section class="card"><p class="muted"><?=$legacy?'Read-only copy of the original website audit trail, retained for historical continuity. These events do not grant MIS access.':'Login, user administration, role changes and settings activity. Reporting decisions and evidence are retained in each submission’s activity history.'?></p><div class="table-scroll"><table><thead><tr><th>ID</th><th>Actor</th><th>Action</th><th>Time</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['username_snapshot']??'System')?></td><td><?=e($r['action'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination"><?php if($page>1):?><a href="?source=<?=$legacy?'legacy':'mis'?>&amp;page=<?=$page-1?>">Previous</a><?php endif;?><span>Page <?=$page?></span><?php if($next):?><a href="?source=<?=$legacy?'legacy':'mis'?>&amp;page=<?=$page+1?>">Next</a><?php endif;?></nav></section><?php pageEnd();?>
